  "privStorage": "Selaimen tallennus",
  "privOther": "Muut nykyiset toiminnot",
  "privProviders": "Palveluntarjoajat ja kansainväliset siirrot",
  "privRetention": "Säilytys ja poistaminen",
  "privRights": "Oikeutesi",
  "noticeReopen": "Tallennusilmoitus",
  "noticeLabel": "Ilmoitus selaimen tallennuksesta",
  "noticeText": "Cook käyttää selaimen tallennusta käyttämiisi ruoanlaitto- ja kirjautumistoimintoihin. Mainonta- tai analytiikkatallennusta ei lisätä.",
  "noticeClose": "Sulje tallennusilmoitus",
  "privDraftLabel": "Luonnos – päivitetty 28. lokakuuta 2026.",
  "privDraft": "Tiliominaisuuksia testataan parhaillaan. Alla olevat ylläpitäjän ja palveluiden tiedot on täydennettävä ennen julkista julkaisua.",
  "privWho1": "Cookia ylläpitää [ylläpitäjän virallinen nimi ja postiosoite]. Tietosuojaa koskevat kysymykset ja pyynnöt: [tietosuojan sähköpostiosoite]. Nämä tiedot on täydennettävä ennen rekisteröitymisen avaamista.",
  "privWhat1": "Kun luot tilin, käytämme sähköpostiosoitettasi, tilin tunnistetta, salasanatunnistautumisen tietoja ja vahvistuksen tilaa tilisi tarjoamiseen ja suojaamiseen. Tunnistautumispalvelu käsittelee salasanat turvallisina tiivisteinä; Cook ei tallenna luettavia salasanoja. Tallennamme keittiön asettelun, valitun kielen, teeman ja mittayksiköt, jotta asetuksesi palautuvat kaikilla laitteilla. Tilin luomiseen tarvitaan sähköpostiosoite ja salasana; reseptejä voi selata ilman tiliä.",
  "privWhat2": "Tilin ja asetusten käsittely on välttämätöntä pyytämäsi tilipalvelun tarjoamiseksi (tietosuoja-asetuksen 6 artiklan 1 kohdan b alakohta). Rajallisia tietoturva- ja väärinkäytösten estämisen tietoja voidaan käsitellä oikeutetun edun perusteella (6 artiklan 1 kohdan f alakohta), kun se on tarpeellista ja intressivertailu sen sallii. Vahvistus- ja salasanan palautusviestit ovat palveluviestejä, eivät markkinointia. Tiliominaisuus ei lisää mainontaa eikä analytiikkaa.",
  "privStorage1": "Cook käyttää sessionStoragea keittiösi, ruoanlaiton etenemisen ja valintojesi siirtämiseen saman välilehden sivujen välillä. Kun olet kirjautunut, siinä on myös kirjautumisistuntosi. Selain tyhjentää sen yleensä välilehden istunnon päättyessä, mutta selaimen istunnon palautus voi säilyttää sen. Uloskirjautuminen tyhjentää Cookin välilehtitiedot. Tallennusilmoituksen sulkeminen tallentuu vain kyseiseen välilehteen. Cookin omat skriptit eivät aseta evästeitä. Verkkopalvelun ylläpitäjillä tai palveluntarjoajilla voi olla omaa tietoturvaan liittyvää käsittelyä, joka on dokumentoitava ennen julkaisua.",
  "privStorage2": "OK ja tallennusilmoituksen sulkemispainike vain sulkevat ilmoituksen. Ne eivät salli analytiikkaa, mainontaa tai muuta valinnaista seurantaa. Tuleva ei-välttämätön tallennus edellyttää erillistä valintaa ennen sen alkamista, ja kieltäytymisen ja peruuttamisen on oltava yhtä helppoa.",
  "privOther1": "Reseptiluettelon nykyinen puhetoiminto pyytää country.is-palvelulta IP-osoitteesi perusteella likimääräisen maan puhekielen valitsemiseksi. Jos käytät mikrofonitunnistusta, selaimesi voi lähettää ääntä puheentunnistuspalvelulleen. Voit myös kirjoittaa ainekset. Nämä palveluntarjoajat, niiden käytännöt ja toimintojen oikeusperuste on tarkistettava ennen julkista julkaisua.",
  "privProviders1": "Suunniteltu tilipalvelu: Supabase (hallinnoitu PostgreSQL ja tunnistautuminen), tietokanta valitulla EU-alueella. Sähköpostipalvelu: [palveluntarjoaja]. Verkkosivuston ylläpito: [palveluntarjoaja]. Ylläpitäjän on vahvistettava todelliset palveluntarjoajat, käsittelysopimukset, alihankkijat, lokien sijainnit ja mahdolliset siirrot ETA-alueen ulkopuolelle. EU-alueella sijaitseva tietokanta ei yksinään sulje pois kansainvälisiä siirtoja. Ilmoita tarvittaessa sovellettava tietosuojan riittävyyttä koskeva päätös tai sopimukselliset suojatoimet ja miten niistä saa kopion.",
  "privRetention1": "Tilin asetukset säilytetään niin kauan kuin tilisi on aktiivinen. Voit pyytää poistamista yllä mainitun tietosuojayhteyden kautta. Ennen julkaisua ylläpitäjän on määritettävä poistopyyntöjen käsittelytapa, vahvistamattomien tilien vanhentuminen sekä tietoturvalokien ja varmuuskopioiden säilytysajat. Poistetut tiedot voivat säilyä käyttörajoitetuissa varmuuskopioissa dokumentoidun säilytysajan loppuun.",
  "privRights1": "Sovellettavista edellytyksistä riippuen voit pyytää pääsyä tietoihin, niiden oikaisemista, poistamista, käsittelyn rajoittamista tai siirtämistä tai vastustaa oikeutettuun etuun perustuvaa käsittelyä. Ota yhteyttä yllä mainittuun ylläpitäjään; pyyntöihin vastataan yleensä kuukauden kuluessa, ja mahdollinen lain sallima jatkoaika perustellaan. Voit tehdä valituksen valvontaviranomaiselle, kuten Unkarin NAIH:lle osoitteessa naih.hu. Cook ei käytä tilin asetuksia automaattisiin päätöksiin, joilla on oikeusvaikutuksia tai vastaavia merkittäviä vaikutuksia.",
  "favOnly": "Vain suosikit",
  "favAdd": "Lisää suosikkeihin",
  "favAdded": "Lisätty suosikkeihin",
