  "Fill the pot": "Täytä kattila",
  "Fill the large pot with # L cold water. Don't add oil.": "Täytä iso kattila # l:lla kylmää vettä. Älä lisää öljyä.",
  "Pot filled": "Kattila täytetty",
  "Put it on the stove": "Nosta liedelle",
  "Put the pot on the largest burner, turn it to HIGH and put the lid on (it boils faster).": "Nosta kattila suurimmalle levylle, käännä levy SUURELLE ja laita kansi päälle (kiehuu nopeammin).",
  "Lid on, burner on high": "Kansi päällä, levy suurella",
  "Wait for the boil": "Odota kiehumista",
  "Let the water come to a full rolling boil. Meanwhile, start the prep.": "Anna veden kiehua kunnolla ja voimakkaasti. Aloita sillä välin esivalmistelut.",
  "Big bubbles break the surface all the time": "Isoja kuplia nousee pintaan koko ajan",
